/**
 * Tranche economics.
 *
 * VERIFIED against 100 real deals in "Fairtide Fund III Series 1 LLC Tranche 77
 * 2026-07-14 Transaction report.xlsx" — a real locked tranche exported from CRM.
 * See FINDINGS.md §1 for the full check. Hit rates on those 100 rows:
 *
 *   Total_Investor_Contribution = Bill_of_Sale_Amount - Pre_Pay_Amount        100/100
 *   ITC_Amount                  = Bill_of_Sale_Amount * Tax_Credit_Percentage 100/100
 *   Pre_Pay_Amount              = Amount * SOW% + Additional_Pre_Pay          100/100
 *   Bill_of_Sale_Amount         = Amount * <investor multiplier, 1.2>         100/100
 *
 * DO NOT port `Deals-formulaAudit.ds` here. Its BoS formula
 * (Amount * SOW% / Pre_Paid_Percentage_of_Bill_of_Sale) matches 8/100 — exactly the
 * rows where Additional_Pre_Pay is zero — and it omits Additional_Pre_Pay entirely.
 * Its alerting block is commented out in the Deluge, almost certainly because it was
 * crying wolf on ~92% of deals.
 */

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

/** CRM stores several of these as picklist/text strings (".7465", ".40"). */
export function num(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).trim();
  if (s === '' || s === '-None-' || s === 'null') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/**
 * Tax credit tier from the EC/DC rubric.
 * Base ITC 30%, +10 energy community, +10 domestic content — consistent with every
 * row in Tranche 77 and with the federal ITC structure. The deal's own
 * Tax_Credit_Percentage wins when present; this is the fallback and the explainer.
 */
export function taxCreditFor(deal) {
  const stored = num(deal.Tax_Credit_Percentage);
  const ec = isEC(deal);
  const dc = isDC(deal);
  const derived = round2(0.3 + (ec ? 0.1 : 0) + (dc ? 0.1 : 0));
  return {
    value: stored ?? derived,
    derived,
    ec,
    dc,
    // Worth surfacing: if these disagree, the rubric on the deal is stale.
    disagrees: stored !== null && Math.abs(stored - derived) > 0.001,
  };
}

export const isEC = (d) => String(d.Energy_Community_Tax_Eligible ?? '').toLowerCase() === 'yes';
export const isDC = (d) => String(d.Domestic_Content ?? '').toLowerCase().startsWith('eligible');

/** The EC / DC / Std chips from Gabe's mockup. */
export function tagsFor(deal) {
  const t = [];
  if (isEC(deal)) t.push({ key: 'EC', label: 'EC', title: deal.Energy_Community_Title || 'Energy community eligible' });
  if (isDC(deal)) t.push({ key: 'DC', label: 'DC', title: 'Domestic content eligible' });
  if (!t.length) t.push({ key: 'Std', label: 'Std', title: 'Standard — no ITC adders' });
  return t;
}

/**
 * Price one deal.
 *
 * @param {object} deal   CRM Deal-shaped record
 * @param {object} [opts]
 * @param {number} [opts.bosMultiplier]  investor's Bill-of-Sale multiplier (Fairtide = 1.2).
 *                                       When absent we fall back to the deal's own stored
 *                                       Bill_of_Sale_Amount so live records still render.
 */
export function priceDeal(deal, opts = {}) {
  const amount = num(deal.Amount) ?? 0;
  const sowPct = num(deal.Pre_Pay_Pct_of_Statement_of_Work) ?? 0;
  const storedBos = num(deal.Bill_of_Sale_Amount);
  const storedPrePay = num(deal.Pre_Pay_Amount);
  const mult = opts.bosMultiplier ?? null;

  // `Additional_Pre_Pay` was a column in the tranche EXPORT but is NOT a field on the CRM
  // Deals module (verified live — absent from a full record dump and from the metadata).
  // So on live records it is always absent and CRM's own Pre_Pay_Amount formula field is
  // the authority. We only compute prepay ourselves for sample rows, which carry the
  // export's Additional_Pre_Pay and no server to ask.
  const addlPrePay = num(deal.Additional_Pre_Pay) ?? 0;
  const prePay = storedPrePay ?? round2(amount * sowPct + addlPrePay);

  // Prefer the investor multiplier (that's the whole point of picking an investor).
  // Fall back to whatever CRM already computed so unpriced states still show something.
  const bos = mult !== null ? round2(amount * mult) : storedBos;
  const priced = bos !== null && bos !== undefined;

  const tc = taxCreditFor(deal);
  const investorContribution = priced ? round2(bos - prePay) : null;
  const itc = priced ? round2(bos * tc.value) : null;

  return {
    amount,
    sowPct,
    addlPrePay,
    prePay,
    bos,
    bosMultiplier: mult,
    bosFromMultiplier: mult !== null,
    investorContribution,
    itc,
    taxCredit: tc,
    bosPct: num(deal.Pre_Paid_Percentage_of_Bill_of_Sale),
    priced,
    kw: num(deal.System_Size) ?? 0,
    kwh: num(deal.Battery_kWh_Size) ?? 0,
    // Sanity flag: our multiplier disagreeing with CRM's stored BoS means the investor
    // multiplier is wrong, or this deal was priced under a different investor.
    driftVsCrm:
      priced && storedBos != null && mult !== null ? round2(bos - storedBos) : null,
  };
}

/**
 * Tranche roll-up. Mirrors what `automation.trancheBtn_updtTotals1` /
 * `automation.updtTranche` compute server-side, plus the weighted percentages
 * and adder totals from Gabe's mockup.
 *
 * Weighted percentages are weighted by `Amount` — a straight mean would let a $5k
 * deal swing the number as hard as a $60k one.
 */
export function trancheTotals(rows, adders = []) {
  const t = {
    count: 0,
    unpriced: 0,
    kw: 0,
    kwh: 0,
    amount: 0,
    prePay: 0,
    bos: 0,
    investorContribution: 0,
    itc: 0,
    wSowPct: 0,
    wBosPct: 0,
    adders: 0,
    byState: {},
  };
  let wAmt = 0;
  let wBosAmt = 0;

  for (const r of rows) {
    const p = r.calc;
    t.count += 1;
    if (!p.priced) {
      t.unpriced += 1;
      continue;
    }
    t.kw += p.kw;
    t.kwh += p.kwh;
    t.amount += p.amount;
    t.prePay += p.prePay;
    t.bos += p.bos;
    t.investorContribution += p.investorContribution;
    t.itc += p.itc;

    if (p.amount) {
      t.wSowPct += p.sowPct * p.amount;
      wAmt += p.amount;
      if (p.bosPct !== null) {
        t.wBosPct += p.bosPct * p.amount;
        wBosAmt += p.amount;
      }
    }
    const st = r.deal.Customer_State || '—';
    t.byState[st] = (t.byState[st] || 0) + 1;
  }

  t.wSowPct = wAmt ? t.wSowPct / wAmt : 0;
  t.wBosPct = wBosAmt ? t.wBosPct / wBosAmt : 0;
  t.adders = round2(adders.reduce((s, a) => s + (num(a.amount) ?? 0), 0));

  for (const k of ['kw', 'kwh', 'amount', 'prePay', 'bos', 'investorContribution', 'itc']) {
    t[k] = round2(t[k]);
  }
  // Adders are charges to the investor, so they lift investor contribution.
  t.investorContributionWithAdders = round2(t.investorContribution + t.adders);
  return t;
}

/**
 * Wave 2/3 — margin allocation.
 *
 * Gabe: "it's not an algorithm." Correct. Price every deal under every investor, hand
 * each to whoever contributes most, and expose the gap to the runner-up so a human can
 * see what overriding costs.
 *
 * Precondition he named: every rubric must be priced for every investor, or the
 * comparison is meaningless. Unpriced ⇒ not eligible, which falls out of priceFor
 * returning null.
 *
 * Returns recommendations. Never mutates a deal. (His rule, stated twice.)
 */
export function allocate(deals, investors, priceFor) {
  return deals.map((deal) => {
    const bids = investors
      .map((inv) => {
        const row = priceFor(deal, inv);
        if (!row) {
          return {
            investor: inv,
            eligible: false,
            value: null,
            reason: `No pricing for ${deal.Customer_State || '—'}`,
          };
        }
        const p = priceDeal(deal, { bosMultiplier: num(row.bosMultiplier) });
        return { investor: inv, eligible: p.priced, value: p.investorContribution, pricing: row };
      })
      .sort((a, b) => (b.value ?? -Infinity) - (a.value ?? -Infinity));

    const eligible = bids.filter((b) => b.eligible);
    const [best, runnerUp] = eligible;

    return {
      deal,
      bids,
      recommended: best?.investor ?? null,
      value: best?.value ?? null,
      marginGap: best && runnerUp ? round2(best.value - runnerUp.value) : null,
      eligibleCount: eligible.length,
    };
  });
}

export { round2 };
