import './styles.css';
import { priceDeal, trancheTotals, tagsFor, allocate, num, round2 } from './calc.js';
import {
  POOLS, poolFor, hasFinal, loadDeals, loadInvestors, loadPoolViews,
  loadRecentTranches, priceFor, pricingGaps, SOURCE, isLive, fallback,
  POOL_QUERIES, poolCounts,
} from './data.js';
import { roleForUser, viewAsOptions, can, denyReason, CAPS, ROLES } from './roles.js';
import { whenReady, currentUser, orgInfo, inZoho, WRITES_ENABLED } from './zoho.js';
import { diag, note, summary } from './diag.js';

/**
 * Injected by Vite at build time (see vite.config.js). Rendered at the top of the widget
 * so "has the new build loaded in Zoho?" is answerable at a glance — both Zoho and
 * GitHub Pages cache hard enough that it is a real question on every deploy.
 */
const BUILD = typeof __BUILD__ !== 'undefined' ? __BUILD__ : { version: 'dev', sha: 'local', built: '—' };

/* ------------------------------------------------------------------ utils */
const $ = (s, r = document) => r.querySelector(s);
const el = (t, c, txt) => { const n = document.createElement(t); if (c) n.className = c; if (txt != null) n.textContent = txt; return n; };
const money = (n) => n == null ? '—' : n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const moneyK = (n) => n == null ? '—' : Math.abs(n) >= 1000 ? '$' + Math.round(n / 1000).toLocaleString() + 'K' : money(n);
const pct = (n) => n == null ? '—' : (n * 100).toFixed(1) + '%';
const initials = (s) => String(s || '?').split(/\s+/).slice(0, 2).map((w) => w[0]).join('').toUpperCase();

/* ------------------------------------------------------------------ state */
const S = {
  deals: [], investors: [], recent: [], poolViews: [],
  investorId: null,
  pool: 'available',
  picked: new Set(),
  stateFilter: new Set(),
  realUser: null, realRole: ROLES.observer,
  viewAs: null,          // null ⇒ acting as the real user
  adders: [
    { label: 'Standard financing fee', amount: 0, fixed: true },
    { label: 'Tax insurance', amount: 0, fixed: true },
  ],
  targetLock: new Date(Date.now() + 3 * 864e5).toISOString().slice(0, 10),
};

const actingUser = () => S.viewAs ?? { name: S.realUser?.full_name ?? 'Unknown user', email: S.realUser?.email ?? null, role: S.realRole };
const actingRole = () => actingUser().role;
const investor = () => S.investors.find((i) => i.id === S.investorId) ?? null;

/* ------------------------------------------------------------------ derive */
function dealsInPool(key) {
  return S.deals.filter((d) => poolFor(d) === key);
}

function visibleDeals() {
  let list = dealsInPool(S.pool);
  if (S.stateFilter.size) list = list.filter((d) => S.stateFilter.has(d.Customer_State));
  return list;
}

function priced(deal) {
  const inv = investor();
  const row = inv ? priceFor(deal, inv) : null;
  const calc = priceDeal(deal, { bosMultiplier: row ? num(row.bosMultiplier) : null });
  return { deal, calc, eligible: !!row };
}

const pickedRows = () => [...S.picked].map((id) => {
  const d = S.deals.find((x) => x.id === id);
  return d ? priced(d) : null;
}).filter(Boolean);

/* ------------------------------------------------------------------ render */
function render() {
  renderWho();
  renderHead();
  renderPools();
  renderPoolTable();
  renderSummary();
  renderAdders();
  renderWorking();
  renderActions();
  renderRecent();
}

function renderWho() {
  const u = actingUser();
  const role = u.role;
  const simulating = !!S.viewAs;

  const box = $('#who');
  box.innerHTML = '';

  const left = el('div', 'who-l');
  left.append(el('div', 'avatar', initials(u.name)));
  const idBlock = el('div');
  idBlock.append(el('div', 'who-name', u.name));
  const sub = el('div', 'who-sub');
  sub.textContent = u.email ?? (S.viewAs ? 'simulated role' : 'no email on record');
  if (simulating) sub.textContent += `  ·  simulated (really signed in as ${S.realUser?.full_name ?? 'unknown'})`;
  idBlock.append(sub);
  left.append(idBlock);
  const pill = el('span', `role-pill ${role.key === 'investor_coordinator' ? 'coordinator' : role.key === 'observer' ? 'observer' : ''}`, role.label);
  pill.title = role.blurb;
  left.append(pill);

  const ver = el('span', 'build', `v${BUILD.version}`);
  ver.title = `build ${BUILD.sha} · ${BUILD.built}`;
  left.append(ver);

  const right = el('div', 'who-r');
  right.append(el('label', '', 'View as'));
  const sel = el('select');
  sel.id = 'viewAs';
  const meOpt = el('option', '', `Me — ${S.realUser?.full_name ?? 'signed-in user'}`);
  meOpt.value = '';
  sel.append(meOpt);
  for (const o of viewAsOptions()) {
    const opt = el('option', '', `${o.name} · ${o.role.label}`);
    opt.value = o.id;
    if (S.viewAs?.id === o.id) opt.selected = true;
    sel.append(opt);
  }
  sel.onchange = (e) => {
    S.viewAs = e.target.value ? viewAsOptions().find((o) => o.id === e.target.value) : null;
    render();
  };
  right.append(sel);

  box.append(left, right);

  const caps = el('div', 'caps');
  for (const [cap, label] of [
    [CAPS.BUILD, 'Build tranche'], [CAPS.LOCK, 'Lock + documents'],
    [CAPS.SWAP, 'Swap deals'], [CAPS.PRICING, 'Edit pricing'], [CAPS.REPORT, 'Reporting'],
  ]) {
    caps.append(el('span', `cap ${can(role, cap) ? '' : 'off'}`, label));
  }
  box.append(caps);
}

function renderHead() {
  const inv = investor();
  const sel = $('#investor');
  sel.innerHTML = '';
  for (const i of S.investors) {
    const o = el('option', '', i.Account_Name + (i.real ? '' : '  [sample]'));
    o.value = i.id;
    if (i.id === S.investorId) o.selected = true;
    sel.append(o);
  }
  $('#targetLock').textContent = S.targetLock;
  $('#invNote').textContent = inv?.note ?? '';
}

function renderPools() {
  const bar = $('#pools');
  bar.innerHTML = '';
  bar.append(el('span', 'lbl', 'Pool:'));
  for (const p of POOLS) {
    const n = dealsInPool(p.key).length;
    const b = el('button', `pool ${S.pool === p.key ? 'active' : ''}`, `${p.label} · ${n}`);
    b.title = p.hint;
    b.onclick = () => { S.pool = p.key; render(); };
    bar.append(b);
  }
}

function renderPoolTable() {
  const pool = POOLS.find((p) => p.key === S.pool);
  const all = dealsInPool(S.pool);
  const list = visibleDeals();

  const states = [...new Set(all.map((d) => d.Customer_State))].sort();
  const fbox = $('#filters');
  fbox.innerHTML = '';
  for (const st of states) {
    const on = S.stateFilter.has(st);
    const b = el('button', `pool ${on ? 'active' : ''}`, st);
    b.onclick = () => { on ? S.stateFilter.delete(st) : S.stateFilter.add(st); render(); };
    fbox.append(b);
  }
  $('#shown').textContent = `${list.length} of ${all.length} shown`;

  const body = $('#poolBody');
  body.innerHTML = '';

  const groups = pool.subdivide
    ? [{ label: 'Has a final', items: list.filter(hasFinal) }, { label: 'No final yet', items: list.filter((d) => !hasFinal(d)) }]
    : [{ label: null, items: list }];

  let rendered = 0;
  for (const g of groups) {
    if (!g.items.length) continue;
    if (g.label) {
      const tr = el('tr');
      const td = el('td', 'grouphdr', g.label);
      td.colSpan = 5;
      tr.append(td);
      body.append(tr);
    }
    for (const d of g.items.slice(0, 60)) { body.append(dealRow(d)); rendered += 1; }
  }
  if (!rendered) {
    const tr = el('tr');
    const td = el('td', 'empty', 'No deals match this pool and filter.');
    td.colSpan = 5;
    tr.append(td);
    body.append(tr);
  }
  const more = list.length - Math.min(list.length, 60);
  $('#poolFoot').textContent = more > 0 ? `+ ${more} more deals in pool` : '';
  $('#poolFoot').hidden = more <= 0;
}

function dealRow(d) {
  const p = priced(d);
  const inTranche = S.picked.has(d.id);
  const role = actingRole();
  const mayBuild = can(role, CAPS.BUILD);

  const tr = el('tr');

  const c1 = el('td');
  c1.append(el('div', 'dname', d.Deal_Name));
  c1.append(el('div', 'dsub', `${d.Account_Name ?? '—'} · ${d.Deal_Type ?? ''}`));
  tr.append(c1);

  tr.append(el('td', '', d.Customer_State ?? '—'));

  const c3 = el('td');
  for (const t of tagsFor(d)) {
    const s = el('span', `tag ${t.key}`, t.label);
    s.title = t.title;
    c3.append(s);
  }
  tr.append(c3);

  const c4 = el('td', 'r');
  if (p.eligible) {
    c4.append(el('div', '', money(p.calc.bos)));
    c4.append(el('div', 'dsub', `IC ${money(p.calc.investorContribution)}`));
  } else {
    c4.append(el('div', 'blocked', 'Not eligible'));
    c4.append(el('div', 'dsub', `No pricing for ${d.Customer_State}`));
  }
  tr.append(c4);

  const c5 = el('td', 'c');
  if (p.eligible) {
    const b = el('button', `mini ${inTranche ? 'in' : ''}`, inTranche ? '✓' : 'Add');
    b.disabled = !mayBuild;
    if (!mayBuild) b.title = denyReason(role, CAPS.BUILD);
    b.onclick = () => { inTranche ? S.picked.delete(d.id) : S.picked.add(d.id); render(); };
    c5.append(b);
  } else {
    c5.append(el('span', 'dsub', '—'));
  }
  tr.append(c5);

  return tr;
}

function renderSummary() {
  const rows = pickedRows();
  const t = trancheTotals(rows, S.adders);
  $('#sCount').textContent = t.count;
  $('#sIC').textContent = moneyK(t.investorContributionWithAdders);
  $('#sBosPct').textContent = pct(t.wBosPct);
  $('#sSowPct').textContent = pct(t.wSowPct);
  $('#sBos').textContent = money(t.bos);
  $('#sPrePay').textContent = money(t.prePay);
  $('#sItc').textContent = money(t.itc);
  $('#sKw').textContent = `${t.kw.toFixed(1)} kW`;
}

function renderAdders() {
  const box = $('#adderLines');
  box.innerHTML = '';
  const mayEdit = can(actingRole(), CAPS.BUILD);

  S.adders.forEach((a, i) => {
    const row = el('div', 'line');
    row.append(el('span', '', a.label));
    const right = el('span', 'v');
    const inp = el('input');
    inp.type = 'number';
    inp.value = a.amount;
    inp.step = '1';
    inp.disabled = !mayEdit;
    inp.style.cssText = 'width:88px;text-align:right;font:inherit;border:0.5px solid var(--border);border-radius:4px;padding:2px 6px;';
    inp.onchange = (e) => { S.adders[i].amount = Number(e.target.value) || 0; render(); };
    right.append(inp);
    row.append(right);
    box.append(row);
  });

  const total = round2(S.adders.reduce((s, a) => s + (Number(a.amount) || 0), 0));
  $('#adderTotal').textContent = money(total);
  $('#addAdder').disabled = !mayEdit;
}

function renderWorking() {
  const rows = pickedRows();
  const box = $('#working');
  box.innerHTML = '';
  const mayBuild = can(actingRole(), CAPS.BUILD);

  if (!rows.length) {
    box.append(el('div', 'empty', 'No deals yet — add from the pool.'));
    return;
  }
  for (const r of rows.slice(0, 40)) {
    const row = el('div', 'wrow');
    const l = el('div');
    l.append(el('div', '', r.deal.Deal_Name.slice(0, 42)));
    l.append(el('div', 'dsub', `${r.deal.Account_Name ?? '—'} · ${r.deal.Customer_State}`));
    const rt = el('div', 'who-l');
    rt.append(el('span', 'amt', money(r.calc.bos)));
    const x = el('button', 'x', '✕');
    x.disabled = !mayBuild;
    x.onclick = () => { S.picked.delete(r.deal.id); render(); };
    rt.append(x);
    row.append(l, rt);
    box.append(row);
  }
  if (rows.length > 40) box.append(el('div', 'foot', `+ ${rows.length - 40} more`));
}

function renderActions() {
  const rows = pickedRows();
  const role = actingRole();
  const mayLock = can(role, CAPS.LOCK);

  const lock = $('#lock');
  lock.disabled = !mayLock || !rows.length;
  const deny = $('#lockDeny');
  deny.textContent = mayLock ? '' : denyReason(role, CAPS.LOCK) ?? '';
  deny.hidden = mayLock;

  $('#preview').disabled = !rows.length;
  $('#status').className = `pill ${rows.length ? 'draft' : 'open'}`;
  $('#status').textContent = rows.length ? 'Draft' : 'Empty';

  const inv = investor();
  const gaps = inv ? pricingGaps(S.deals, inv) : [];
  const gbox = $('#gaps');
  gbox.innerHTML = '';
  if (gaps.length) {
    gbox.hidden = false;
    gbox.append(el('div', 'sum-t', `Pricing gaps — ${inv.Account_Name}`));
    for (const g of gaps) {
      const r = el('div', 'sum-row');
      r.append(el('span', '', g.state), el('span', 'v', `${g.count} deal${g.count > 1 ? 's' : ''} blocked`));
      gbox.append(r);
    }
  } else gbox.hidden = true;
}

function renderRecent() {
  const box = $('#recent');
  box.innerHTML = '';
  for (const t of S.recent) {
    const c = el('div', 'rcard');
    c.append(el('div', 'd', t.date));
    c.append(el('div', 'n', `${t.investor} · ${t.deals ?? '—'} deals`));
    const b = el('div', 'b');
    b.append(el('span', '', moneyK(t.total)));
    const st = el('span', '', t.status);
    st.style.color = t.status === 'Locked' ? 'var(--text-success)' : 'var(--text-warning)';
    b.append(st);
    c.append(b);
    box.append(c);
  }
}

/* ------------------------------------------------------------------ modals */
function openModal(title, build) {
  $('#modalTitle').textContent = title;
  const body = $('#modalBody');
  body.innerHTML = '';
  build(body);
  $('#modal').hidden = false;
}
const closeModal = () => { $('#modal').hidden = true; };

function previewModal() {
  const rows = pickedRows();
  const inv = investor();
  const t = trancheTotals(rows, S.adders);
  const name = `${inv.Account_Name} Tranche ${S.targetLock}`;

  openModal('Preview — documents and economics', (b) => {
    b.append(el('div', 'mono', name));
    b.append(el('p', 'note', 'Name pattern comes from automation.Untitled_Function2 — "<Investor Account_Name> Tranche <Tranche_Date>". Downstream report filters depend on this exact string.'));

    for (const [k, v] of [
      ['Deals', String(t.count)], ['Capacity', `${t.kw.toFixed(1)} kW`],
      ['Total pre-pay', money(t.prePay)], ['Total bill of sale', money(t.bos)],
      ['Total adders', money(t.adders)],
      ['Total investor contribution', money(t.investorContributionWithAdders)],
      ['Est. ITC', money(t.itc)],
      ['Weighted pre-pay % BoS', pct(t.wBosPct)], ['Weighted pre-pay % SOW', pct(t.wSowPct)],
    ]) {
      const r = el('div', 'sum-row');
      r.append(el('span', '', k), el('span', 'v', v));
      b.append(r);
    }

    b.append(el('div', 'sum-t', 'Documents that would generate on lock'));
    const ul = el('ul', 'doclist');
    for (const d of [
      'BOS and A&AA — Zoho Sign template 154758000019030075',
      'Tranche Schedule PDF — Creator print template',
      'Amendment — template 154758000019523687 (amendments only)',
    ]) ul.append(el('li', '', d));
    b.append(ul);
    b.append(el('p', 'note', 'Signer is hardcoded to "Jeff Hawkinson" in send_tranche_envelope. Writer preview-before-generate is what Gabe asked for and is not wired yet.'));
  });
}

function lockModal() {
  const rows = pickedRows();
  const inv = investor();
  const t = trancheTotals(rows, S.adders);

  openModal('Lock and generate documents', (b) => {
    const warn = el('div', 'banner warn');
    warn.innerHTML = '<strong>Writes are disabled in this build.</strong> Nothing below will happen. This screen shows exactly what locking would do.';
    b.append(warn);

    b.append(el('div', 'mono', `${inv.Account_Name} Tranche ${S.targetLock}\n${t.count} deals · ${money(t.bos)} bill of sale · ${money(t.investorContributionWithAdders)} investor contribution`));

    b.append(el('div', 'sum-t', 'automation.finalizeTranche5 would:'));
    const ul = el('ul', 'doclist');
    for (const s of [
      `Set Avail_for_Purchase = false on all ${t.count} deals`,
      'Set Tranche_Status = "Locked"',
      'Rebuild System_Schedule and WM_JSON subforms',
      'Email the three Investor Relations notification recipients',
      'Snapshot the tranche to Tranche_Logs and each deal to Deal_Logs',
      'Send the BOS and A&AA envelope for signature',
    ]) ul.append(el('li', '', s));
    b.append(ul);
    b.append(el('p', 'note', 'Known live bug to be aware of before this goes on: automation.updtTranche writes the NEW tranche\'s totals onto the OLD tranche when a deal moves between tranches (icsum/bossum reused instead of oldicsum/oldbossum). This tool moves deals between tranches, so it will hit that path.'));
  });
}

function connectionModal() {
  openModal('Connection', (b) => {
    const rows = [
      ['Source', isLive() ? (fallback.active ? 'live requested — fell back to sample' : 'live CRM') : 'sample data'],
      ['Framed by Zoho', diag.framed ? 'yes' : 'no (standalone)'],
      ['SDK handshake', diag.sdkReady ? 'completed' : 'did not complete'],
      ['SDK error', diag.sdkError ?? '—'],
      [
        'serviceOrigin from Zoho',
        // Only call it missing when we actually looked. Standalone never attempts the
        // handshake, and reporting a failure there would send someone chasing nothing.
        diag.params
          ? (diag.params.serviceOrigin ?? 'MISSING — this is why the handshake fails')
          : 'not checked (standalone)',
      ],
      ['Org', diag.org ? `${diag.org.name} (${diag.org.id})` : '—'],
      ['User', diag.user ? diag.user.name : '—'],
      ['CRM profile', diag.user?.profile ?? '—'],
      ['CRM role', diag.user?.role ?? '—'],
      ['Writes', WRITES_ENABLED ? 'ENABLED' : 'disabled'],
      ['Build', `v${BUILD.version} · ${BUILD.sha} · ${BUILD.built}`],
    ];
    for (const [k, v] of rows) {
      const r = el('div', 'sum-row');
      r.append(el('span', '', k), el('span', 'v', String(v)));
      b.append(r);
    }

    if (diag.params) {
      b.append(el('div', 'sum-t', 'Params Zoho passed to the iframe'));
      const pb = el('div', 'mono');
      pb.textContent = Object.keys(diag.params).length
        ? Object.entries(diag.params).map(([k, v]) => `${k} = ${v}`).join('\n')
        : '(none — Zoho appended no query string, so the SDK cannot call back to the parent)';
      b.append(pb);
    }

    // The pool definitions are the least-settled part of the build, so show the exact
    // WHERE clause next to what it returned.
    b.append(el('div', 'sum-t', 'Pool queries'));
    for (const [key, def] of Object.entries(POOL_QUERIES)) {
      const got = poolCounts.value?.[key];
      const box = el('div', 'mono');
      box.textContent =
        `${def.label}  —  ${got === undefined ? 'not run (sample mode)' : got + (typeof got === 'number' ? ' rows' : '')}
` +
        `where ${def.where}
${def.confidence}`;
      b.append(box);
    }

    const s = summary();
    b.append(el('div', 'sum-t', `CRM calls — ${s.ok} ok, ${s.failed} failed, ${s.rows} rows`));

    if (!diag.calls.length) {
      b.append(el('p', 'note', 'No CRM calls made — running on sample data.'));
    }
    for (const c of diag.calls) {
      const box = el('div', 'mono');
      box.style.borderColor = c.ok === false ? 'var(--text-danger)' : 'var(--border)';
      box.textContent =
        `${c.ok === false ? '✕' : '✓'} ${c.kind}  ${c.ms}ms` +
        (c.rows != null ? `  ${c.rows} rows` : '') +
        `
${c.detail}` +
        (c.error ? `

ERROR: ${c.error}` : '');
      b.append(box);
    }
    b.append(el('p', 'note', 'Each entry is a real call to CRM. A failed query here means the widget loaded fine and the query is wrong — a different fix from the embed not loading at all.'));
  });
}

function marginModal() {
  const pool = S.deals.filter((d) => poolFor(d) === 'available');
  const res = allocate(pool, S.investors, priceFor);

  openModal('Maximise margin — recommendation', (b) => {
    b.append(el('p', 'note', 'Wave 2/3. Prices every deal under every investor and recommends whoever contributes most. Recommendation only — it never assigns.'));

    const tbl = el('table', 'atable');
    const head = el('tr');
    for (const h of ['Deal', 'Recommended', 'Margin gap', 'Eligible']) head.append(el('th', '', h));
    tbl.append(head);
    for (const r of res.slice(0, 25)) {
      const tr = el('tr');
      tr.append(el('td', '', r.deal.Deal_Name.slice(0, 34)));
      tr.append(el('td', '', r.recommended?.Account_Name?.replace(' (sample)', '') ?? '— none —'));
      tr.append(el('td', '', r.marginGap == null ? '—' : money(r.marginGap)));
      tr.append(el('td', '', `${r.eligibleCount}/${S.investors.length}`));
      tbl.append(tr);
    }
    b.append(tbl);
    b.append(el('p', 'note', "Gabe's precondition: every rubric must be priced for every investor or this comparison is meaningless. The pricing-gaps panel shows where it currently isn't."));
  });
}

/* ------------------------------------------------------------------ boot */
async function boot() {
  // Identity first — but never let Zoho block the render. Outside CRM (local dev,
  // direct GitHub Pages hit) PageLoad simply never fires, so we time-box it.
  note({ framed: inZoho() });
  if (inZoho()) {
    try {
      await Promise.race([whenReady(), new Promise((r) => setTimeout(r, 10000))]);
      S.realUser = await currentUser();
      await orgInfo();
    } catch (e) {
      console.warn('Zoho init failed — continuing with sample data', e);
    }
  }
  S.realRole = roleForUser(S.realUser);

  // Nobody is signed in (standalone preview) ⇒ default the simulator to an admin so the
  // whole surface is explorable. Inside CRM the real user's own role governs.
  if (!S.realUser) S.viewAs = viewAsOptions()[0];

  const [deals, investors, recent, views] = await Promise.all([
    loadDeals(), loadInvestors(), loadRecentTranches(), loadPoolViews(),
  ]);
  S.deals = deals;
  S.investors = investors;
  S.recent = recent;
  S.poolViews = views;
  S.investorId = investors[0]?.id ?? null;

  const src = $('#srcBanner');
  if (isLive() && !fallback.active) {
    src.className = 'banner info';
    src.innerHTML = `<strong>Live CRM data.</strong> Reads are real; all writes are disabled in this build.`;
  } else if (fallback.active) {
    // The widget loaded fine — it's the data layer that didn't. Say which, because the
    // fixes are in different places (tab/URL config vs CRM permissions or COQL).
    src.className = 'banner warn';
    src.innerHTML =
      `<strong>Widget loaded, but live CRM reads failed — showing sample data.</strong> ` +
      `The embed and the UI are fine; the data call is what broke. Reason: ` +
      `<code>${String(fallback.reason).slice(0, 160)}</code>`;
  } else {
    src.className = 'banner warn';
    src.innerHTML =
      `<strong>Sample data.</strong> Economics are real — taken from Fairtide Fund III Series 1 LLC ` +
      `Tranche 77 (2026-07-14, 100 deals) and used to validate every formula. Customer and installer ` +
      `names are synthetic. Pool assignment is synthetic. Load inside CRM for live records.`;
  }

  $('#investor').onchange = (e) => { S.investorId = e.target.value; S.picked.clear(); render(); };
  $('#refresh').onclick = async () => { S.deals = await loadDeals(); render(); };
  $('#newTranche').onclick = () => { S.picked.clear(); S.adders.forEach((a) => (a.amount = 0)); render(); };
  $('#addAdder').onclick = () => {
    S.adders.push({ label: `Custom adder ${S.adders.length - 1}`, amount: 0 });
    render();
  };
  $('#preview').onclick = previewModal;
  $('#lock').onclick = lockModal;
  $('#margin').onclick = marginModal;
  $('#conn').onclick = connectionModal;
  $('#modalClose').onclick = closeModal;
  $('#modal').onclick = (e) => { if (e.target.id === 'modal') closeModal(); };

  render();
}

boot().catch((e) => {
  console.error(e);
  $('#app').innerHTML = `<div class="banner warn"><strong>Failed to start.</strong> ${e.message}</div>`;
});
